            if random.choice([True, False]):
                clause = {x for x in clause}
            else:
                clause = {-x for x in clause}
            clauses.append(clause)
        return clauses

    def communication_complexity(k_cnf):
        n = len(k_cnf[0])
        return 2 * (n - 1) + k_cnf[0].count(-k_cnf[0][0]) + k_cnf[0].count(k_cnf[0][1])

